settings.custom_css:
/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =========================================================
   RAMIS — PRODUCT GRID RESPONSIVE
   ========================================================= */

/* کارت محصول */
.product-card {
    box-sizing: border-box !important;
    min-width: 0 !important;
    max-width: none !important;
}

/* حذف دکمه تکراری خارج Footer */
.product-card > a.add_to_cart_button {
    display: none !important;
}


/* =========================================================
   TABLET — بدون تغییر
   ========================================================= */

@media (max-width: 1100px) and (min-width: 768px) {

    ul.products.elementor-grid {
        display: grid !important;
        grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        gap: 24px 20px !important;
        box-sizing: border-box !important;
    }

    ul.products.elementor-grid > li.product,
    ul.products.elementor-grid > li.product-card {
        width: 100% !important;
        min-width: 0 !important;
        max-width: none !important;
        margin: 0 !important;
        box-sizing: border-box !important;
    }

    .product-card .woocommerce-LoopProduct-link,
    .product-card .thumbnail,
    .product-card .cardFooter {
        width: 100% !important;
        max-width: 100% !important;
        box-sizing: border-box !important;
    }

    .product-card .thumbnail img {
        width: 100% !important;
        height: auto !important;
        display: block !important;
    }

    .product-card .cardFooter {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 8px !important;
        padding: 10px !important;
    }

    .product-card .cardFooter-right,
    .product-card .cardFooter-left,
    .product-card .addtocart {
        min-width: 0 !important;
        box-sizing: border-box !important;
    }

    .product-card .cardFooter-left {
        display: flex !important;
        align-items: center !important;
        gap: 6px !important;
    }
}


/* =========================================================
   MOBILE — یک کارت در هر ردیف
   ========================================================= */

@media (max-width: 767px) {

    /* یک ستون */
    ul.products.elementor-grid {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) !important;
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        row-gap: 18px !important;
        column-gap: 0 !important;
        box-sizing: border-box !important;
    }

    /* کارت تمام عرض */
    ul.products.elementor-grid > li.product,
    ul.products.elementor-grid > li.product-card {
        width: 100% !important;
        min-width: 0 !important;
        max-width: none !important;
        margin: 0 !important;
        box-sizing: border-box !important;
    }

    .product-card {
        width: 100% !important;
        min-width: 0 !important;
        max-width: none !important;
        overflow: hidden !important;
        border-radius: 14px !important;
        box-sizing: border-box !important;
    }

    /* تصویر */
    .product-card .woocommerce-LoopProduct-link,
    .product-card .thumbnail {
        width: 100% !important;
        max-width: 100% !important;
        box-sizing: border-box !important;
    }

    .product-card .thumbnail img {
        display: block !important;
        width: 100% !important;
        height: auto !important;
    }

    /* عنوان */
    .product-card .woocommerce-loop-product__title {
        font-size: 15px !important;
        line-height: 1.7 !important;
        margin: 12px 14px 6px !important;
        white-space: normal !important;
        overflow: hidden !important;
    }

    /* قیمت */
    .product-card .price {
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100% !important;
        margin: 8px 14px !important;
        min-height: 40px !important;
        font-size: 14px !important;
        box-sizing: border-box !important;
        overflow: hidden !important;
        white-space: nowrap !important;
        text-overflow: ellipsis !important;
    }

    /* Footer */
    .product-card .cardFooter {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        width: 100% !important;
        max-width: 100% !important;
        gap: 8px !important;
        padding: 10px !important;
        box-sizing: border-box !important;
        overflow: hidden !important;
    }

    /* بخش قیمت */
    .product-card .cardFooter-right {
        flex: 1 1 0 !important;
        min-width: 0 !important;
        max-width: 100% !important;
        overflow: hidden !important;
        box-sizing: border-box !important;
    }

    .product-card .prices {
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100% !important;
        overflow: hidden !important;
        box-sizing: border-box !important;
    }

    .product-card .prices .price,
    .product-card .prices bdi {
        max-width: 100% !important;
        overflow: hidden !important;
        white-space: nowrap !important;
        text-overflow: ellipsis !important;
    }

    /* بخش دکمه */
    .product-card .cardFooter-left {
        flex: 0 0 40px !important;
        width: 40px !important;
        min-width: 40px !important;
        max-width: 40px !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        box-sizing: border-box !important;
    }

    .product-card .addtocart {
        width: 40px !important;
        min-width: 40px !important;
        max-width: 40px !important;
        flex: 0 0 40px !important;
        box-sizing: border-box !important;
    }

    .product-card .cardFooter .add_to_cart_button {
        width: 40px !important;
        min-width: 40px !important;
        max-width: 40px !important;
        box-sizing: border-box !important;
    }
}


/* =========================================================
   موبایل خیلی کوچک
   ========================================================= */

@media (max-width: 380px) {

    ul.products.elementor-grid {
        row-gap: 14px !important;
    }

    .product-card .woocommerce-loop-product__title {
        font-size: 14px !important;
    }

    .product-card .cardFooter {
        padding: 8px !important;
    }

    .product-card .cardFooter-left,
    .product-card .addtocart,
    .product-card .cardFooter .add_to_cart_button {
        width: 38px !important;
        min-width: 38px !important;
        max-width: 38px !important;
        flex-basis: 38px !important;
    }
}


/* =========================================================
   حذف موارد اضافی
   ========================================================= */

.pooshe-quick-view-btn,
.product-card .pooshe-badges,
.product-card .pooshe-badge,
.product-card .onsale,
.product-card .new-version,
.pooshe-badge--updated {
    display: none !important;
}


/* =========================================================
   فونت
   ========================================================= */

.product-card,
.product-card * {
    font-family: "Yekan Bakh", sans-serif !important;
}


/* =========================================================
   DESKTOP — بدون تغییر
   ========================================================= */

@media (min-width: 1101px) {

    .product-card .cardFooter {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        gap: 8px !important;
        width: 100% !important;
        box-sizing: border-box !important;
        overflow: hidden !important;
    }

    .product-card .cardFooter-right {
        flex: 1 1 auto !important;
        min-width: 0 !important;
        max-width: 100% !important;
    }

    .product-card .cardFooter-left {
        flex: 0 0 auto !important;
        min-width: 0 !important;
        display: flex !important;
        align-items: center !important;
    }

    .product-card .prices {
        min-width: 0 !important;
        max-width: 100% !important;
        overflow: hidden !important;
        white-space: nowrap !important;
        box-sizing: border-box !important;
    }

    .product-card .price {
        min-width: 0 !important;
        max-width: 100% !important;
        margin: 0 !important;
        overflow: hidden !important;
        white-space: nowrap !important;
        box-sizing: border-box !important;
    }

    .product-card .addtocart {
        flex: 0 0 auto !important;
        width: auto !important;
    }

    .product-card .addtocart .add_to_cart_button {
        flex: 0 0 auto !important;
    }
}

/* =========================================================
   RAMIS — MOBILE PRODUCT FOOTER FINAL
   ========================================================= */

@media (max-width: 767px) {

    /* Footer */
    .product-card .cardFooter {
        display: flex !important;
        align-items: center !important;
        justify-content: flex-start !important;
        width: 100% !important;
        max-width: 100% !important;
        min-width: 0 !important;
        padding: 8px !important;
        margin: 0 !important;
        gap: 8px !important;
        overflow: hidden !important;
        box-sizing: border-box !important;
    }

    /* بخش اصلی Footer */
    .product-card .cardFooter-left {
        display: flex !important;
        align-items: center !important;
        justify-content: flex-start !important;
        flex: 1 1 auto !important;
        width: auto !important;
        min-width: 0 !important;
        max-width: 100% !important;
        gap: 8px !important;
        margin: 0 !important;
        padding: 0 !important;
        box-sizing: border-box !important;
    }

    /* بخش اضافه سمت راست */
    .product-card .cardFooter-right {
        flex: 0 0 auto !important;
        min-width: 0 !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    /* =====================================================
       PRICE
       ===================================================== */

    .product-card .prices {
        flex: 1 1 auto !important;
        width: auto !important;
        min-width: 0 !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;
        box-sizing: border-box !important;
    }

    .product-card .prices .price {
        display: block !important;
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;
        white-space: nowrap !important;
        text-overflow: ellipsis !important;
        box-sizing: border-box !important;
    }

    /* =====================================================
       ADD TO CART
       ===================================================== */

    .product-card .addtocart {
        flex: 0 0 40px !important;
        width: 40px !important;
        min-width: 40px !important;
        max-width: 40px !important;
        height: 40px !important;
        margin: 0 !important;
        padding: 0 !important;
        box-sizing: border-box !important;
    }

    .product-card .cardFooter .add_to_cart_button {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        width: 40px !important;
        min-width: 40px !important;
        max-width: 40px !important;
        height: 40px !important;
        margin: 0 !important;
        padding: 0 !important;
        box-sizing: border-box !important;
        transform: none !important;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 380px) {

    .product-card .cardFooter {
        padding: 7px !important;
        gap: 6px !important;
    }

    .product-card .cardFooter-left {
        gap: 6px !important;
    }

    .product-card .addtocart,
    .product-card .cardFooter .add_to_cart_button {
        width: 38px !important;
        min-width: 38px !important;
        max-width: 38px !important;
        height: 38px !important;
        flex-basis: 38px !important;
    }
}
